head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.grdReg_onviewchange = function(info) {
	if (grdReg.getColumnID(info.colIndex) == "PROCESS_MAIN_AGNT_CD") {
		if (info.newValue == "ALL" || info.newValue == "") {
			dc_reg.setCellData(info.rowIndex, "SALES_LV4_MBR_ID", "");
			grdReg.setDisabled("cell", info.rowIndex, "SALES_LV4_MBR_ID", true);
			grdReg.setDisabled("cell", info.rowIndex, "PROMO_EVT_STORE_QTY", true);
		} else {
			grdReg.setDisabled("cell", info.rowIndex, "SALES_LV4_MBR_ID", false);
			grdReg.setDisabled("cell", info.rowIndex, "PROMO_EVT_STORE_QTY", false);
		}
	}
};
scwin.btnInsert_onclick = function(e) {
	var row = 0;
	if (dc_reg.getRowCount() >= 0) {
		row = dc_reg.getRowCount();
	} else {
		row = grdReg.getRealRowIndex(grdReg.getFocusedRowIndex()) + 1;
	}
	dc_reg.insertRow(row);
	dc_reg.setCellData(row, "REGIST_BY", obj.userId);
	dc_reg.setCellData(row, "REGIST_NM", obj.userNm);
	dc_reg.setCellData(row, "STATUS", "C");
	scwin.cellReadOnly(row);
};
scwin.cellReadOnly = function(row) {
	grdReg.setDisabled("cell", row, "PROCESS_MAIN_AGNT_CD", false);
};
scwin.__numRowAdded = function(num) {
	var tr = ((j) => j.length ? j : $('#mf_grdReg_body_tbody tr'))($('#grdReg_body_tbody tr')).not(".w2grid_hidedRow");
	return tr.length == num;
}
scwin.__selectedVal = function(id, val) {
	return scwin.__getDom(id).innerText == val;
}
scwin.__triggerDbclick = function(id) {
	var node = scwin.__getDom($p.id + id);
	if (document.createEventObject) {
		node.fireEvent('ondblclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondblclick == 'function') {
		node.ondblclick();
	}
}
scwin.setVal = function() {
	scwin.__getObj('grdReg_cell_0_1').click();
}
scwin.setVal2 = function() {
	return scwin.__numRowAdded(2) == true;
}
scwin.setVal3 = function() {
	return scwin.__selectedVal('grdReg_cell_0_1', 'KA사업');
}
scwin.setVal4 = function() {
	scwin.__triggerDbclick('grdReg_cell_0_2');
}
scwin.setVal5 = function() {
	return scwin.__selectedVal('grdReg_cell_0_2', 'Hyper/SSM팀');
}
scwin.setVal6 = function() {
